#!/usr/bin/env bash
# Writes the Homebrew formula for a beta (canary) release to stdout.
#
#   beta-formula.sh <tag> <checksums.txt>  >  Formula/gitswitch-beta.rb
#
# <checksums.txt> is `sha256sum` output for the release binaries
# (gitswitch-<os>-<arch>). The canary workflow runs this and commits the
# result to aksisonline/homebrew-tap, which is what lets a Homebrew install
# move to the beta channel — and keep updating — without gitswitch ever
# replacing a file Homebrew owns:
#
#   brew uninstall gitswitch && brew install aksisonline/tap/gitswitch-beta
#
# (`gitswitch beta` runs exactly that.)
set -euo pipefail

TAG="${1:?usage: beta-formula.sh <tag> <checksums.txt>}"
SUMS="${2:?usage: beta-formula.sh <tag> <checksums.txt>}"
VERSION="${TAG#v}"
BASE="https://github.com/aksisonline/gitswitch/releases/download/${TAG}"

sha() {
  local sum
  sum=$(awk -v f="$1" '{ name = $2; sub(/^\*/, "", name) } name == f { print $1 }' "$SUMS")
  if [ -z "$sum" ]; then
    echo "beta-formula.sh: no checksum for $1 in $SUMS" >&2
    exit 1
  fi
  printf '%s' "$sum"
}

# Fail before writing anything if a platform's checksum is missing — a formula
# with an empty sha256 would break `brew install` for everyone on beta.
for asset in gitswitch-darwin-amd64 gitswitch-darwin-arm64 gitswitch-linux-amd64 gitswitch-linux-arm64; do
  sha "$asset" >/dev/null
done

# One `if` block per platform, in the shape GoReleaser generates for the
# stable formula, so the two formulae read the same.
block() { # <condition> <asset>
  cat <<RUBY
    if $1
      url "${BASE}/$2"
      sha256 "$(sha "$2")"

      define_method(:install) do
        bin.install "$2" => "gitswitch"
      end
    end
RUBY
}

cat <<RUBY
# typed: false
# frozen_string_literal: true

# Generated by .github/scripts/beta-formula.sh in aksisonline/gitswitch for
# each beta release. DO NOT EDIT — changes are overwritten by the next beta.
class GitswitchBeta < Formula
  desc "Manage multiple git profiles locally (beta channel)"
  homepage "https://github.com/aksisonline/gitswitch"
  version "${VERSION}"
  license "Apache-2.0"

  conflicts_with "gitswitch", because: "both install a \`gitswitch\` binary"

  on_macos do
$(block "Hardware::CPU.intel?" "gitswitch-darwin-amd64")
$(block "Hardware::CPU.arm?" "gitswitch-darwin-arm64")
  end

  on_linux do
$(block "Hardware::CPU.intel? && Hardware::CPU.is_64_bit?" "gitswitch-linux-amd64")
$(block "Hardware::CPU.arm? && Hardware::CPU.is_64_bit?" "gitswitch-linux-arm64")
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/gitswitch --version")
  end
end
RUBY
